package com.qualitypilot.campaignlab.execution;
import com.qualitypilot.campaignlab.audience.*;import com.qualitypilot.campaignlab.campaign.CampaignException;import com.qualitypilot.campaignlab.plan.*;import com.qualitypilot.campaignlab.profile.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class ExecutionService{
 private final MarketingPlanRepository plans;private final FlowNodeRepository nodes;private final FlowEdgeRepository edges;private final AudienceCalculationRepository calculations;private final AudienceMemberRepository members;private final SyntheticUserRepository users;private final CampaignRunRepository runs;private final UserJourneyRepository journeys;private final NodeExecutionRepository traces;private final ChannelReceiptRepository receipts;
 public ExecutionService(MarketingPlanRepository p,FlowNodeRepository n,FlowEdgeRepository e,AudienceCalculationRepository c,AudienceMemberRepository m,SyntheticUserRepository u,CampaignRunRepository r,UserJourneyRepository j,NodeExecutionRepository t,ChannelReceiptRepository cr){plans=p;nodes=n;edges=e;calculations=c;members=m;users=u;runs=r;journeys=j;traces=t;receipts=cr;}
 public record RunView(String id,String planId,int audienceBatch,RunStatus status,int totalUsers,Instant startedAt){}
 @Transactional public RunView start(String role,String planId){if(!"operator".equals(role))throw err("PERMISSION_DENIED","operation requires role: operator",HttpStatus.FORBIDDEN);MarketingPlan plan=plans.findById(planId).orElseThrow(()->err("PLAN_NOT_FOUND","marketing plan not found",HttpStatus.NOT_FOUND));if(plan.getStatus()!=PlanStatus.PUBLISHED)throw err("PLAN_NOT_PUBLISHED","only published plan can run",HttpStatus.CONFLICT);AudienceCalculation calc=calculations.findTopByAudienceIdAndRuleVersionOrderByBatchNumberDesc(plan.getAudienceId(),plan.getAudienceVersion()).orElseThrow(()->err("AUDIENCE_BATCH_NOT_FOUND","audience calculation not found",HttpStatus.CONFLICT));List<AudienceMember> audienceMembers=members.findByCalculationIdOrderByUserId(calc.getId());String runId=UUID.randomUUID().toString();CampaignRun run=runs.save(new CampaignRun(runId,planId,calc.getId(),calc.getBatchNumber(),audienceMembers.size(),Instant.now()));boolean waiting=false;for(AudienceMember member:audienceMembers)waiting|=executeUser(runId,planId,member.getUserId());run.finish(waiting);return view(run);}
 @Transactional(readOnly=true) public List<RunView> list(){return runs.findAll().stream().map(this::view).toList();}
 @Transactional(readOnly=true) public List<UserJourney> journeys(String runId){return journeys.findByRunIdOrderByUserId(runId);}
 @Transactional(readOnly=true) public List<NodeExecution> trace(String runId,String userId){if(!runs.existsById(runId))throw err("RUN_NOT_FOUND","run not found",HttpStatus.NOT_FOUND);return traces.findByRunIdAndUserIdOrderById(runId,userId);}
 private boolean executeUser(String runId,String planId,String userId){Instant now=Instant.now();UserJourney journey=journeys.save(new UserJourney(runId,userId,now));Map<String,FlowNode> nodeMap=new HashMap<>();nodes.findByPlanIdOrderById(planId).forEach(n->nodeMap.put(n.getNodeKey(),n));Map<String,List<FlowEdge>> out=new HashMap<>();edges.findByPlanIdOrderById(planId).forEach(e->out.computeIfAbsent(e.getSourceNodeKey(),k->new ArrayList<>()).add(e));FlowNode current=nodeMap.values().stream().filter(n->n.getType()==NodeType.START).findFirst().orElseThrow();String lastReceipt=null;while(true){String result="PASSED",branch=null;Instant resume=null;if(current.getType()==NodeType.MARKETING){lastReceipt=Math.floorMod(Objects.hash(runId,userId,current.getNodeKey()),5)==0?"FAILURE":"SUCCESS";result=lastReceipt;receipts.save(new ChannelReceipt(runId,userId,current.getNodeKey(),current.getConfig(),result,Instant.now()));}else if(current.getType()==NodeType.DELAY){resume=Instant.now().plus(Duration.ofMinutes(Long.parseLong(current.getConfig())));result="WAITING";}else if(current.getType()==NodeType.DECISION){branch=choose(current,userId,lastReceipt);result="BRANCH_"+branch;}else if(current.getType()==NodeType.END)result="SUCCEEDED";traces.save(new NodeExecution(runId,userId,current.getNodeKey(),current.getType().name(),result,branch,Instant.now(),resume));if(current.getType()==NodeType.END){journey.succeeded();return false;}if(current.getType()==NodeType.DELAY){journey.waiting();return true;}List<FlowEdge> candidates=out.getOrDefault(current.getNodeKey(),List.of());String chosen=branch;FlowEdge edge=candidates.stream().filter(e->chosen==null?e.getBranchLabel()==null:chosen.equals(e.getBranchLabel())).findFirst().orElseThrow();current=nodeMap.get(edge.getTargetNodeKey());}}
 private String choose(FlowNode node,String userId,String receipt){String c=node.getConfig();if(c.startsWith("AB:")){int a=Integer.parseInt(c.split(":")[1]);return Math.floorMod(userId.hashCode(),100)<a?"A":"B";}if(c.startsWith("LABEL:")){SyntheticUser u=users.findById(userId).orElseThrow();String[] rule=c.substring(6).split("=",2);boolean match=switch(rule[0]){case "city"->u.getCity().equals(rule[1]);case "memberLevel"->u.getMemberLevel().equals(rule[1]);case "newUser"->Boolean.toString(u.isNewUser()).equals(rule[1]);case "riskLevel"->u.getRiskLevel().equals(rule[1]);case "marketingAllowed"->Boolean.toString(u.isMarketingAllowed()).equals(rule[1]);default->false;};return match?"YES":"NO";}return "SUCCESS".equals(receipt)?"SUCCESS":"FAILURE";}
 private RunView view(CampaignRun r){return new RunView(r.getId(),r.getPlanId(),r.getAudienceBatch(),r.getStatus(),r.getTotalUsers(),r.getStartedAt());}private CampaignException err(String c,String m,HttpStatus s){return new CampaignException(c,m,s);}
}
